<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\Support;
class AccountController extends Controller {
 public function address(Request $r){$v=$r->validate(['recipient'=>'required|string|max:150','phone'=>['required','regex:/^09[0-9]{9}$/'],'region'=>'nullable|string|max:120','province'=>'required|string|max:120','city'=>'required|string|max:120','barangay'=>'required|string|max:120','street'=>'required|string|max:200','postal_code'=>['required','regex:/^[0-9]{4}$/']]);\App\Services\Geography::validate($v);$u=auth()->user();$old=\App\Services\Municipalities::address($u->id);if(in_array($u->role,['sorting_center','rider'])&&$old&&!\App\Services\Municipalities::matches($old,(object)$v))Support::fail('city','Your registered service municipality cannot be changed here. Ask the logistics administrator to review your territory.');unset($v['region']);DB::transaction(function()use($v,$old,$u){if($old)DB::table('addresses')->where('id',$old->id)->where('user_id',$u->id)->update($v+['updated_at'=>now()]);else DB::table('addresses')->insert($v+['user_id'=>$u->id,'is_default'=>1,'created_at'=>now(),'updated_at'=>now()]);});return $r->expectsJson()?response()->json(['message'=>'Address updated.']):back()->with('success','Address updated.');}
 public function territory(Request $r){abort_unless(auth()->user()->role==='logistics_admin',403);$v=$r->validate(['center_id'=>'required|integer','region'=>'required|string','province'=>'required|string','city'=>'required|string','barangay'=>'required|string','street'=>'required|string|max:200','postal_code'=>['required','regex:/^[0-9]{4}$/'],'reason'=>'required|string|min:10|max:300']);\App\Services\Geography::validate($v);DB::transaction(function()use($v){$c=DB::table('sorting_centers')->where('id',$v['center_id'])->lockForUpdate()->first();abort_unless($c,404);$key=\App\Services\Municipalities::key($v['province'],$v['city']);if(DB::table('sorting_centers')->where('municipality_key',$key)->where('id','!=',$c->id)->exists())Support::fail('city','A sorting center already owns this municipality.');if($c->municipality_key!==$key&&DB::table('parcels')->where('center_id',$c->id)->whereNotIn('status',['COMPLETED','CANCELLED','RETURN_RECEIVED','RETURNED','DELIVERED'])->exists())Support::fail('center_id','Finish or reassign current parcels before changing the service municipality.');$u=DB::table('users')->find($c->user_id);$a=\App\Services\Municipalities::address($u->id);$address=\Illuminate\Support\Arr::only($v,['province','city','barangay','street','postal_code'])+['recipient'=>$u->name,'phone'=>$u->phone??'','is_default'=>1,'updated_at'=>now()];if($a)DB::table('addresses')->where('id',$a->id)->update($address);else DB::table('addresses')->insert($address+['user_id'=>$u->id,'created_at'=>now()]);DB::table('sorting_centers')->where('id',$c->id)->update(['municipality_key'=>$key,'city'=>$v['city'],'province'=>$v['province'],'updated_at'=>now()]);foreach(DB::table('users')->where('company_id',$u->id)->where('role','rider')->pluck('id') as $id)\App\Services\Fleet::address($id,$u->id);Support::audit('center-territory','sorting_center',$c->id,$c,['city'=>$v['city'],'province'=>$v['province']],$v['reason']);});return back()->with('success','Service municipality saved. Local couriers now serve this municipality.');}
 public function status(Request $r,int $id){$v=$r->validate(['status'=>'required|in:active,archived,suspended,banned','reason'=>'required|string|min:5|max:300']);$roles=auth()->user()->role==='admin'?['buyer','seller']:['sorting_center','rider'];abort_unless(in_array(auth()->user()->role,['admin','logistics_admin']),403);abort_if($id===auth()->id(),422);
 DB::transaction(function()use($id,$v,$roles){$u=DB::table('users')->where('id',$id)->whereIn('role',$roles)->lockForUpdate()->first();abort_unless($u,404);DB::table('users')->where('id',$id)->update(['account_status'=>$v['status'],'account_status_reason'=>$v['reason'],'active'=>$v['status']==='active','online'=>0,'api_token_expires_at'=>null,'remember_token'=>null,'updated_at'=>now()]);Support::audit('account-status','user',$id,$u,$v,$v['reason']);Support::notify([$id],'Your account is '.$v['status'].': '.$v['reason']);Support::email($id,'LokaShop account status','Your account is '.$v['status'].'. '.$v['reason']);});return back()->with('success','Account status updated. Records and order history were retained.');}
}
